#include <iostream>
using namespace std;

int main() {
    int n, sum = 0;
    cin >> n;

    for (int i = 1; i <= n; i++) {
        if (i % 2 == 0) {
            sum += i;
        }
    }

    cout << sum;
    return 0;
}

#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    int n;
    cin >> n;

    int prev, x;
    cin >> prev;

    int len = 1, best = 1;

    for (int i = 1; i < n; i++) {
        cin >> x;

        if (x > prev) len++;
        else len = 1;

        best = max(best, len);
        prev = x;
    }

    cout << best;
}
